-- Module 2: profiles, addresses and partner onboarding (section 5).
-- partner_services is created with the service catalogue (Module 3): it cannot exist before the services table.
-- partner_profiles.main_service_category_id has no foreign key yet; the service catalogue migration adds it.

-- ---------------------------------------------------------------------------------------------------------------
-- Public ids (NHCUST0001, ...): generated by the database from one sequence per table, so concurrent inserts never
-- collide. At least four digits; more once a sequence passes 9999.
-- ---------------------------------------------------------------------------------------------------------------
CREATE FUNCTION nexhome_public_id(prefix TEXT, seq_value BIGINT) RETURNS VARCHAR(24)
	LANGUAGE sql IMMUTABLE AS
$$ SELECT prefix || lpad(seq_value::TEXT, greatest(4, length(seq_value::TEXT)), '0') $$;

CREATE SEQUENCE nexhome_admin_profiles_public_id_seq;
CREATE SEQUENCE nexhome_customer_profiles_public_id_seq;
CREATE SEQUENCE nexhome_addresses_public_id_seq;
CREATE SEQUENCE nexhome_partner_profiles_public_id_seq;

-- ---------------------------------------------------------------------------------------------------------------
-- Admin / sub-admin profile with its single registered address
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE nexhome_admin_profiles (
	id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	public_id     VARCHAR(24)  NOT NULL
		DEFAULT nexhome_public_id('NHADMI', nextval('nexhome_admin_profiles_public_id_seq')),
	user_id       BIGINT       NOT NULL REFERENCES nexhome_users (id) ON DELETE RESTRICT,
	first_name    VARCHAR(100) NOT NULL,
	last_name     VARCHAR(100) NOT NULL,
	employee_code VARCHAR(30),
	department    VARCHAR(100),
	job_title     VARCHAR(100),
	address_line1 VARCHAR(255) NOT NULL,
	address_line2 VARCHAR(255),
	landmark      VARCHAR(255),
	city          VARCHAR(100) NOT NULL,
	state         VARCHAR(100) NOT NULL,
	postal_code   VARCHAR(12)  NOT NULL,
	country_code  VARCHAR(2)   NOT NULL DEFAULT 'IN',
	creation_date TIMESTAMPTZ  NOT NULL DEFAULT now(),
	created_by    BIGINT REFERENCES nexhome_users (id),
	updated_date  TIMESTAMPTZ  NOT NULL DEFAULT now(),
	updated_by    BIGINT REFERENCES nexhome_users (id),
	attribute1    VARCHAR(255),
	attribute2    VARCHAR(255),
	attribute3    VARCHAR(255),
	attribute4    VARCHAR(255),
	attribute5    VARCHAR(255),
	CONSTRAINT uq_nexhome_admin_profiles_public_id UNIQUE (public_id),
	CONSTRAINT uq_nexhome_admin_profiles_user UNIQUE (user_id)
);

-- Employee codes are optional, but unique when present
CREATE UNIQUE INDEX ux_nexhome_admin_profiles_employee_code
	ON nexhome_admin_profiles (employee_code) WHERE employee_code IS NOT NULL;

-- ---------------------------------------------------------------------------------------------------------------
-- Customer profile and preferences: one per account
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE nexhome_customer_profiles (
	id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	public_id          VARCHAR(24)  NOT NULL
		DEFAULT nexhome_public_id('NHCUST', nextval('nexhome_customer_profiles_public_id_seq')),
	user_id            BIGINT       NOT NULL REFERENCES nexhome_users (id) ON DELETE RESTRICT,
	first_name         VARCHAR(100) NOT NULL,
	last_name          VARCHAR(100) NOT NULL,
	date_of_birth      DATE,
	-- PREFERRED_CONTACT_LANGUAGE value code
	preferred_language VARCHAR(20),
	marketing_consent  BOOLEAN      NOT NULL DEFAULT FALSE,
	creation_date      TIMESTAMPTZ  NOT NULL DEFAULT now(),
	created_by         BIGINT REFERENCES nexhome_users (id),
	updated_date       TIMESTAMPTZ  NOT NULL DEFAULT now(),
	updated_by         BIGINT REFERENCES nexhome_users (id),
	attribute1         VARCHAR(255),
	attribute2         VARCHAR(255),
	attribute3         VARCHAR(255),
	attribute4         VARCHAR(255),
	attribute5         VARCHAR(255),
	CONSTRAINT uq_nexhome_customer_profiles_public_id UNIQUE (public_id),
	CONSTRAINT uq_nexhome_customer_profiles_user UNIQUE (user_id)
);

-- ---------------------------------------------------------------------------------------------------------------
-- Customer service addresses: many per customer, at most one default
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE nexhome_addresses (
	id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	public_id     VARCHAR(24)   NOT NULL
		DEFAULT nexhome_public_id('NHADDR', nextval('nexhome_addresses_public_id_seq')),
	user_id       BIGINT        NOT NULL REFERENCES nexhome_users (id) ON DELETE RESTRICT,
	contact_name  VARCHAR(150)  NOT NULL,
	mobile_number VARCHAR(15)   NOT NULL,
	-- ADDRESS_TYPE value code
	address_type  VARCHAR(60)   NOT NULL,
	label         VARCHAR(50),
	address_line1 VARCHAR(255)  NOT NULL,
	address_line2 VARCHAR(255),
	landmark      VARCHAR(255),
	city          VARCHAR(100)  NOT NULL,
	state         VARCHAR(100)  NOT NULL,
	postal_code   VARCHAR(12)   NOT NULL,
	country_code  VARCHAR(2)    NOT NULL DEFAULT 'IN',
	latitude      NUMERIC(10, 7) CHECK (latitude BETWEEN -90 AND 90),
	longitude     NUMERIC(10, 7) CHECK (longitude BETWEEN -180 AND 180),
	is_default    BOOLEAN       NOT NULL DEFAULT FALSE,
	creation_date TIMESTAMPTZ   NOT NULL DEFAULT now(),
	created_by    BIGINT REFERENCES nexhome_users (id),
	updated_date  TIMESTAMPTZ   NOT NULL DEFAULT now(),
	updated_by    BIGINT REFERENCES nexhome_users (id),
	attribute1    VARCHAR(255),
	attribute2    VARCHAR(255),
	attribute3    VARCHAR(255),
	attribute4    VARCHAR(255),
	attribute5    VARCHAR(255),
	CONSTRAINT uq_nexhome_addresses_public_id UNIQUE (public_id),
	CONSTRAINT ck_nexhome_addresses_coordinates CHECK ((latitude IS NULL) = (longitude IS NULL))
);

CREATE INDEX ix_nexhome_addresses_user ON nexhome_addresses (user_id);
-- At most one default address per customer
CREATE UNIQUE INDEX ux_nexhome_addresses_one_default ON nexhome_addresses (user_id) WHERE is_default;

-- ---------------------------------------------------------------------------------------------------------------
-- Partner profile: personal details, registered address, work preferences and approval.
-- A DRAFT may be saved incomplete; ck_nexhome_partner_profiles_submitted requires the mandatory fields once the
-- profile leaves DRAFT (they are NOT NULL in the design).
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE nexhome_partner_profiles (
	id                             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	public_id                      VARCHAR(24)   NOT NULL
		DEFAULT nexhome_public_id('NHPART', nextval('nexhome_partner_profiles_public_id_seq')),
	user_id                        BIGINT        NOT NULL REFERENCES nexhome_users (id) ON DELETE RESTRICT,
	first_name                     VARCHAR(80)   NOT NULL,
	middle_name                    VARCHAR(80),
	last_name                      VARCHAR(80)   NOT NULL,
	-- AES-GCM ciphertext; never stored or logged in plain text
	aadhaar_number_encrypted       TEXT,
	alternate_contact_number       VARCHAR(10),
	is_adult                       BOOLEAN,
	-- PREFERRED_CONTACT_LANGUAGE value code, e.g. te, hi, en
	preferred_contact_language     VARCHAR(40),
	address_line1                  VARCHAR(300),
	address_line2                  VARCHAR(255),
	landmark                       VARCHAR(255),
	locality                       VARCHAR(100),
	city                           VARCHAR(100),
	state                          VARCHAR(100),
	postal_code                    CHAR(6) CHECK (postal_code ~ '^[1-9][0-9]{5}$'),
	country_code                   VARCHAR(2)    NOT NULL DEFAULT 'IN',
	latitude                       NUMERIC(10, 7) CHECK (latitude BETWEEN -90 AND 90),
	longitude                      NUMERIC(10, 7) CHECK (longitude BETWEEN -180 AND 180),
	registration_date              DATE          NOT NULL DEFAULT CURRENT_DATE,
	registered_by                  BIGINT        NOT NULL REFERENCES nexhome_users (id),
	-- SKILL_CATEGORY value code
	skill_category                 VARCHAR(30),
	years_experience               SMALLINT CHECK (years_experience BETWEEN 0 AND 60),
	-- The foreign key to the service categories table is added by the service catalogue migration
	main_service_category_id       BIGINT,
	-- JSON array of skill codes
	additional_skills              JSONB,
	-- PREFERRED_ARRANGEMENT value code
	preferred_arrangement          VARCHAR(40),
	-- PAYMENT_BASIS value code
	payment_basis                  VARCHAR(20),
	expected_earnings_inr          NUMERIC(10, 2) CHECK (expected_earnings_inr > 0),
	visit_charge_inr               NUMERIC(10, 2) CHECK (visit_charge_inr >= 0),
	minimum_job_payment_inr        NUMERIC(10, 2) CHECK (minimum_job_payment_inr >= 0),
	previous_work_details          TEXT,
	-- JSON array of area codes or names
	service_areas                  JSONB         NOT NULL DEFAULT '[]'::jsonb
		CHECK (jsonb_typeof(service_areas) = 'array'),
	max_travel_km                  NUMERIC(5, 1) CHECK (max_travel_km BETWEEN 0 AND 999.9),
	-- JSON object of day -> AVAILABILITY_SLOT codes, e.g. {"MONDAY": ["MORNING", "EVENING"]}
	weekly_availability            JSONB         NOT NULL DEFAULT '{}'::jsonb
		CHECK (jsonb_typeof(weekly_availability) = 'object'),
	-- WEEKEND_AVAILABILITY value code
	weekend_availability           VARCHAR(20),
	emergency_contact_name         VARCHAR(120),
	-- EMERGENCY_CONTACT_RELATIONSHIP value code
	emergency_contact_relationship VARCHAR(60),
	emergency_contact_number       VARCHAR(10),
	emergency_contact_permission   BOOLEAN       NOT NULL DEFAULT FALSE,
	-- PARTNER_ONBOARDING_STATUS, VERIFICATION_STATUS and PARTNER_AVAILABILITY_STATUS value codes
	onboarding_status              VARCHAR(60)   NOT NULL,
	verification_status            VARCHAR(60)   NOT NULL,
	availability_status            VARCHAR(60)   NOT NULL,
	approved_by                    BIGINT REFERENCES nexhome_users (id),
	approved_at                    TIMESTAMPTZ,
	rejection_reason               TEXT,
	creation_date                  TIMESTAMPTZ   NOT NULL DEFAULT now(),
	created_by                     BIGINT REFERENCES nexhome_users (id),
	updated_date                   TIMESTAMPTZ   NOT NULL DEFAULT now(),
	updated_by                     BIGINT REFERENCES nexhome_users (id),
	attribute1                     VARCHAR(255),
	attribute2                     VARCHAR(255),
	attribute3                     VARCHAR(255),
	attribute4                     VARCHAR(255),
	attribute5                     VARCHAR(255),
	CONSTRAINT uq_nexhome_partner_profiles_public_id UNIQUE (public_id),
	CONSTRAINT uq_nexhome_partner_profiles_user UNIQUE (user_id),
	CONSTRAINT ck_nexhome_partner_profiles_coordinates CHECK ((latitude IS NULL) = (longitude IS NULL)),
	CONSTRAINT ck_nexhome_partner_profiles_approved_by CHECK (approved_at IS NULL OR approved_by IS NOT NULL),
	CONSTRAINT ck_nexhome_partner_profiles_adult CHECK (onboarding_status <> 'APPROVED' OR is_adult),
	CONSTRAINT ck_nexhome_partner_profiles_submitted CHECK (onboarding_status = 'DRAFT' OR (
		is_adult IS NOT NULL AND preferred_contact_language IS NOT NULL AND address_line1 IS NOT NULL
		AND locality IS NOT NULL AND city IS NOT NULL AND state IS NOT NULL AND postal_code IS NOT NULL
		AND skill_category IS NOT NULL AND years_experience IS NOT NULL AND preferred_arrangement IS NOT NULL
		AND payment_basis IS NOT NULL AND expected_earnings_inr IS NOT NULL AND max_travel_km IS NOT NULL
		AND weekend_availability IS NOT NULL AND jsonb_array_length(service_areas) > 0))
);

CREATE INDEX ix_nexhome_partner_profiles_verification_onboarding
	ON nexhome_partner_profiles (verification_status, onboarding_status);
CREATE INDEX ix_nexhome_partner_profiles_availability_city ON nexhome_partner_profiles (availability_status, city);

-- ---------------------------------------------------------------------------------------------------------------
-- Partner identity and certification documents. The files live in protected object storage.
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE nexhome_partner_documents (
	id                        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	partner_id                BIGINT      NOT NULL REFERENCES nexhome_partner_profiles (id) ON DELETE RESTRICT,
	-- DOCUMENT_TYPE value code
	document_type             VARCHAR(60) NOT NULL,
	document_number_encrypted TEXT,
	file_storage_key          TEXT        NOT NULL,
	-- VERIFICATION_STATUS value code
	verification_status       VARCHAR(60) NOT NULL,
	verified_by               BIGINT REFERENCES nexhome_users (id),
	verified_at               TIMESTAMPTZ,
	expiry_date               DATE,
	rejection_reason          TEXT,
	creation_date             TIMESTAMPTZ NOT NULL DEFAULT now(),
	created_by                BIGINT REFERENCES nexhome_users (id),
	updated_date              TIMESTAMPTZ NOT NULL DEFAULT now(),
	updated_by                BIGINT REFERENCES nexhome_users (id),
	attribute1                VARCHAR(255),
	attribute2                VARCHAR(255),
	attribute3                VARCHAR(255),
	attribute4                VARCHAR(255),
	attribute5                VARCHAR(255),
	CONSTRAINT ck_nexhome_partner_documents_verified_by CHECK (verified_at IS NULL OR verified_by IS NOT NULL)
);

CREATE INDEX ix_nexhome_partner_documents_partner_status
	ON nexhome_partner_documents (partner_id, verification_status);

-- ---------------------------------------------------------------------------------------------------------------
-- Partner payout bank accounts: at most one primary per partner
-- ---------------------------------------------------------------------------------------------------------------
CREATE TABLE nexhome_partner_bank_accounts (
	id                       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	partner_id               BIGINT       NOT NULL REFERENCES nexhome_partner_profiles (id) ON DELETE RESTRICT,
	account_holder_name      VARCHAR(150) NOT NULL,
	-- AES-GCM ciphertext; only the last four digits are ever shown
	account_number_encrypted TEXT         NOT NULL,
	account_number_last4     VARCHAR(4)   NOT NULL CHECK (account_number_last4 ~ '^[0-9]{4}$'),
	ifsc_code                VARCHAR(11)  NOT NULL CHECK (ifsc_code ~ '^[A-Z]{4}0[A-Z0-9]{6}$'),
	bank_name                VARCHAR(150),
	-- VERIFICATION_STATUS value code
	verification_status      VARCHAR(60)  NOT NULL,
	-- Set by the payout integration (Module 7)
	gateway_beneficiary_id   VARCHAR(150),
	is_primary               BOOLEAN      NOT NULL DEFAULT TRUE,
	creation_date            TIMESTAMPTZ  NOT NULL DEFAULT now(),
	created_by               BIGINT REFERENCES nexhome_users (id),
	updated_date             TIMESTAMPTZ  NOT NULL DEFAULT now(),
	updated_by               BIGINT REFERENCES nexhome_users (id),
	attribute1               VARCHAR(255),
	attribute2               VARCHAR(255),
	attribute3               VARCHAR(255),
	attribute4               VARCHAR(255),
	attribute5               VARCHAR(255)
);

CREATE INDEX ix_nexhome_partner_bank_accounts_partner ON nexhome_partner_bank_accounts (partner_id);
-- At most one primary account per partner
CREATE UNIQUE INDEX ux_nexhome_partner_bank_accounts_one_primary
	ON nexhome_partner_bank_accounts (partner_id) WHERE is_primary;

ALTER SEQUENCE nexhome_admin_profiles_public_id_seq OWNED BY nexhome_admin_profiles.public_id;
ALTER SEQUENCE nexhome_customer_profiles_public_id_seq OWNED BY nexhome_customer_profiles.public_id;
ALTER SEQUENCE nexhome_addresses_public_id_seq OWNED BY nexhome_addresses.public_id;
ALTER SEQUENCE nexhome_partner_profiles_public_id_seq OWNED BY nexhome_partner_profiles.public_id;

-- ---------------------------------------------------------------------------------------------------------------
-- Lookups used by Module 2 that section 3 does not list. ADDRESS_TYPE, PARTNER_ONBOARDING_STATUS,
