-- ---------------------------------------------------------------------------------------------------------------
-- Functions guarding the Module 2 endpoints. Owners always manage their own profile, addresses, documents and bank
-- accounts; these functions cover acting on other users' records.
-- ---------------------------------------------------------------------------------------------------------------
INSERT INTO nexhome_functions (function_module, function_code, function_name, function_type, description,
                               created_by, updated_by)
VALUES ('PROFILE', 'PROFILE_MANAGE', 'Manage Customer Profiles', 'FEATURE',
        'Read: view any customer profile and addresses. Write: create and update them for customers. Delete: '
            || 'delete customer addresses.', 1, 1),
       ('PARTNER', 'PARTNER_ONBOARDING_MANAGE', 'Manage Partner Onboarding', 'FEATURE',
        'Read: view partner profiles, documents and bank accounts. Write: create and update them for partners, '
            || 'review profiles, verify documents and bank accounts. Delete: delete partner documents and bank '
            || 'accounts.', 1, 1);

UPDATE nexhome_functions
SET description = 'Read: list admins and sub-admins and view staff profiles. Write: create and update staff profiles.',
    updated_by  = 1,
    updated_date = now()
WHERE function_code = 'STAFF_MANAGE';

INSERT INTO nexhome_role_functions (role_id, function_id, can_read, can_write, can_delete, created_by, updated_by)
SELECT r.id, f.id, g.can_read, g.can_write, g.can_delete, 1, 1
FROM (VALUES ('ADMIN', 'PROFILE_MANAGE', TRUE, TRUE, TRUE),
             ('ADMIN', 'PARTNER_ONBOARDING_MANAGE', TRUE, TRUE, TRUE),
             ('SUB_ADMIN', 'PROFILE_MANAGE', TRUE, FALSE, FALSE),
             ('SUB_ADMIN', 'PARTNER_ONBOARDING_MANAGE', TRUE, FALSE, FALSE)) AS g (role_code, function_code, can_read,
                                                                                  can_write, can_delete)
JOIN nexhome_roles r ON r.code = g.role_code
JOIN nexhome_functions f ON f.function_code = g.function_code;

-- Admins may now maintain staff profiles too (only a super user may change a super user's profile)
UPDATE nexhome_role_functions rf
SET can_write = TRUE, updated_by = 1, updated_date = now()
FROM nexhome_roles r, nexhome_functions f
WHERE rf.role_id = r.id AND rf.function_id = f.id AND r.code = 'ADMIN' AND f.function_code = 'STAFF_MANAGE';
